  // First initialization of the fastify root instance
  if (this[kCanSetNotFoundHandler] === undefined) {
    this[kCanSetNotFoundHandler] = true
  }
  if (this[kFourOhFourContext] === undefined) {
    this[kFourOhFourContext] = null
  }

